const FINAL_BOSS_BY_ACTOR_STATE = new Map(HMH_FINAL_BOSS_ANIMATION_PACK.assets.map((asset) => [`${asset.actorId}/${asset.state}`, Object.freeze(asset)]));
export function finalBossAnimationAssetByActorState(actorId, state) { return FINAL_BOSS_BY_ACTOR_STATE.get(`${actorId}/${state}`) ?? null; }
